CREATE UNIQUE INDEX uq_academic_years_id_owner ON academic_years (id, owner_teacher_id);
CREATE UNIQUE INDEX uq_groups_lineage ON groups (id, academic_year_id, owner_teacher_id);
CREATE TABLE academic_calendars (id TEXT PRIMARY KEY NOT NULL, academic_year_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, timezone TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (academic_year_id), UNIQUE (id, academic_year_id, owner_teacher_id), FOREIGN KEY (academic_year_id, owner_teacher_id) REFERENCES academic_years(id, owner_teacher_id) ON DELETE RESTRICT);
CREATE TABLE academic_terms (id TEXT PRIMARY KEY NOT NULL, calendar_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, code TEXT NOT NULL CHECK (code IN ('T1','T2','T3')), starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, UNIQUE (calendar_id, code), UNIQUE (id, calendar_id, academic_year_id, owner_teacher_id), CHECK (starts_on <= ends_on), FOREIGN KEY (calendar_id, academic_year_id, owner_teacher_id) REFERENCES academic_calendars(id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT);
CREATE TABLE calendar_holidays (id TEXT PRIMARY KEY NOT NULL, calendar_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, CHECK (starts_on <= ends_on), FOREIGN KEY (calendar_id, academic_year_id, owner_teacher_id) REFERENCES academic_calendars(id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT);
CREATE TABLE weekly_timetable_slots (id TEXT PRIMARY KEY NOT NULL, calendar_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, owner_teacher_id TEXT NOT NULL, group_id TEXT NOT NULL, weekday INTEGER NOT NULL CHECK (weekday BETWEEN 1 AND 7), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, CHECK (starts_at < ends_at AND length(starts_at) = 5 AND length(ends_at) = 5), UNIQUE (id, calendar_id, academic_year_id, owner_teacher_id, group_id), FOREIGN KEY (calendar_id, academic_year_id, owner_teacher_id) REFERENCES academic_calendars(id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT, FOREIGN KEY (group_id, academic_year_id, owner_teacher_id) REFERENCES groups(id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT);
CREATE TABLE real_class_sessions (id TEXT PRIMARY KEY NOT NULL, owner_teacher_id TEXT NOT NULL, academic_year_id TEXT NOT NULL, group_id TEXT NOT NULL, calendar_id TEXT NOT NULL, term_id TEXT NOT NULL, slot_id TEXT NOT NULL, local_date TEXT NOT NULL, timezone TEXT NOT NULL, slot_starts_at TEXT NOT NULL, slot_ends_at TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY (calendar_id, academic_year_id, owner_teacher_id) REFERENCES academic_calendars(id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT, FOREIGN KEY (term_id, calendar_id, academic_year_id, owner_teacher_id) REFERENCES academic_terms(id, calendar_id, academic_year_id, owner_teacher_id) ON DELETE RESTRICT, FOREIGN KEY (slot_id, calendar_id, academic_year_id, owner_teacher_id, group_id) REFERENCES weekly_timetable_slots(id, calendar_id, academic_year_id, owner_teacher_id, group_id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX uq_real_sessions_active_teacher ON real_class_sessions(owner_teacher_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX uq_real_sessions_slot_date ON real_class_sessions(slot_id, local_date);
CREATE INDEX idx_real_sessions_year_date ON real_class_sessions(owner_teacher_id, academic_year_id, local_date);
CREATE TABLE real_class_session_requests (id TEXT PRIMARY KEY NOT NULL, owner_teacher_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('START','END')), fingerprint TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES real_class_sessions(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE (owner_teacher_id, idempotency_key));
